/**
 * @description Auto-retry sweep: every 15 minutes (four hourly jobs at :00, :15, :30 and :45) it finds Failed outbound
 * transactions whose Next Retry At has come (and whose event is still active with Auto Retry Max above 0), sets them to Retry with Auto Retries + 1 and clears Next Retry At, in
 * chunks of 50. The transaction trigger then sends each chunk through the normal Sender job, and the attempt is logged
 * as Auto Retry. Only temporary failures of events with Auto Retry Max get a Next Retry At (IntegrationHubRetryPlan);
 * permanent rejections are never resubmitted. Nothing runs while Disable Publishing is ticked for the user the jobs run
 * as. A sandbox refresh removes the jobs: schedule them again from the Monitor or with
 * IntegrationHubMaintenance.scheduleAll().
 * @group Integration Hub
 */
public with sharing class IntegrationHubAutoRetry implements Schedulable, Database.Batchable<SObject> {

    /** @description Start of the job names; the minute follows, e.g. "Integration Hub Auto Retry :15". */
    public static final String JOB_PREFIX = 'Integration Hub Auto Retry :';
    /** @description Transactions per chunk: one chunk is one Sender job. */
    public static final Integer CHUNK = 50;
    /** The minutes of the hour the four jobs run at. */
    private static final List<Integer> MINUTES = new List<Integer>{ 0, 15, 30, 45 };
    /**
     * @description Failed outbound transactions waiting for auto-retry whose event is still active and still has Auto
     * Retry Max above 0 (an event switched off since then is left alone). Binds: dir, failed.
     */
    public static final String WAITING = 'Direction__c = :dir AND Status__c = :failed AND Next_Retry_At__c != null '
        + 'AND Event__r.Active__c = true AND Event__r.Auto_Retry_Max__c > 0';
    private static final String DUE = WAITING + ' AND Next_Retry_At__c <= :now';

    /**
     * @description The names of the four jobs, ":00" first.
     * @return the job names
     */
    public static List<String> jobNames() {
        List<String> names = new List<String>();
        for (Integer m : MINUTES) {
            names.add(JOB_PREFIX + String.valueOf(m).leftPad(2, '0'));
        }
        return names;
    }

    /**
     * @description Schedules the jobs that are missing; a job that already exists is left alone, so calling it twice
     * schedules nothing more. The jobs run as the current user.
     * @return how many jobs were scheduled now
     */
    @SuppressWarnings('PMD.OperationWithLimitsInLoop')
    public static Integer scheduleJobs() {
        // At most four System.schedule calls (one per missing job), far below the limit of 100 scheduled jobs.
        Set<String> existing = scheduledNames();
        Integer added = 0;
        for (Integer m : MINUTES) {
            String name = JOB_PREFIX + String.valueOf(m).leftPad(2, '0');
            if (!existing.contains(name)) {
                System.schedule(name, '0 ' + m + ' * * * ?', new IntegrationHubAutoRetry());
                added++;
            }
        }
        return added;
    }

    /**
     * @description How many of the four jobs exist (a sandbox refresh removes them).
     * @return 0 to 4
     */
    public static Integer scheduledCount() {
        return scheduledNames().size();
    }

    private static Set<String> scheduledNames() {
        Set<String> names = new Set<String>();
        for (SObject row : IntegrationHubData.query('SELECT CronJobDetail.Name FROM CronTrigger WHERE CronJobDetail.Name IN :names',
                new Map<String, Object>{ 'names' => jobNames() })) {
            names.add((String) row.getSObject('CronJobDetail').get('Name'));
        }
        return names;
    }

    /**
     * @description Failed outbound transactions whose automatic retry is due now (counted up to 10,000).
     * @return how many are due
     */
    public static Integer dueCount() {
        return IntegrationHubData.countQuery('SELECT COUNT() FROM IH_Transaction__c WHERE ' + DUE + ' LIMIT 10000', dueBinds());
    }

    /**
     * @description Scheduled run: starts the sweep when something is due and publishing is not disabled.
     * @param sc the schedulable context
     */
    public void execute(SchedulableContext sc) {
        if (!IntegrationHub.publishingDisabled() && dueCount() > 0) {
            Database.executeBatch(new IntegrationHubAutoRetry(), CHUNK);
        }
    }

    /**
     * @description Batch start: the due transactions, the longest waiting first.
     * @param bc the batch context
     * @return the transactions
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return IntegrationHubData.locator('SELECT Id, Auto_Retries__c FROM IH_Transaction__c WHERE ' + DUE
            + ' ORDER BY Next_Retry_At__c', dueBinds());
    }

    /**
     * @description Batch chunk: sets the chunk to Retry; the transaction trigger sends it in one Sender job.
     * @param bc the batch context
     * @param scope the transactions
     */
    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (IntegrationHub.publishingDisabled()) {
            return;
        }
        IntegrationHubData.updateEach(retryRows(scope));
    }

    /**
     * @description Batch end: the trigger already sent every chunk.
     * @param bc the batch context
     */
    public void finish(Database.BatchableContext bc) {
        return;
    }

    /**
     * @description The changes that hand due transactions to the Sender: Status Retry, Auto Retries + 1, Next Retry At
     * cleared, error cleared (each attempt keeps its own error).
     * @param scope the due transactions (Id, Auto_Retries__c)
     * @return the rows to update
     */
    @TestVisible
    private static List<IH_Transaction__c> retryRows(List<SObject> scope) {
        List<IH_Transaction__c> rows = new List<IH_Transaction__c>();
        for (SObject row : scope) {
            IH_Transaction__c t = (IH_Transaction__c) row;
            rows.add(new IH_Transaction__c(Id = t.Id, Status__c = IntegrationHub.STATUS_RETRY, Next_Retry_At__c = null,
                Auto_Retries__c = (t.Auto_Retries__c == null ? 0 : t.Auto_Retries__c) + 1, Error_Message__c = null,
                Error_Summary__c = null));
        }
        return rows;
    }

    private static Map<String, Object> dueBinds() {
        return new Map<String, Object>{ 'dir' => IntegrationHub.OUTBOUND, 'failed' => IntegrationHub.STATUS_FAILED, 'now' => System.now() };
    }
}
